import { people } from './company-model.mjs';
const esc = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const tourOrder = ['dana','daniel','ben','priya','nina','ava','elena','marcus','leah'];
export const verdicts = {dana:'win',daniel:'diff',ben:'win',priya:'win',nina:'win',marcus:'diff',ava:'stuck',elena:'stuck',leah:'glue'};
const verdictLabels = {win:'AI WIN',diff:'DIFFERENT WAY',stuck:'STRUGGLING',glue:'THE GLUE'};
const badges = {dana:'Personal value',daniel:'Useful foundation',ben:'Private success',priya:'Reusable method',nina:'Team-built tool',marcus:'Quiet practice',ava:'Hidden effort',elena:'Wants a way in',leah:'Manual assembly'};
const toolIcons = {Claude:'claude.svg','Ask Parkside':'ms-teams.svg',Copilot:'copilot.webp','Ask Ops':'ms-teams.svg',Grok:'grok.svg'};
const shortRoles = {dana:'CEO',daniel:'IT',ben:'Sales',priya:'Finance',nina:'Operations',marcus:'Accounts',ava:'Service',elena:'Coordination',leah:'Chief of staff'};
const person = id => people.find(p=>p.id===id);
const avatar = (id,cls='') => {const p=person(id);return `<span class="ws-avatar v-${verdicts[id]} ${cls}" aria-hidden="true">${p.name[0]}<img src="assets/${toolIcons[p.ai]}" alt=""></span>`;};
const ghostFace = '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="9" r="4"/><path d="M4 21c1-4.5 4.4-6.5 8-6.5s7 2 8 6.5"/></svg>';
const ghost = (label,cls='') => `<span class="ws-ghost ${cls}"><span class="ws-avatar ghost" aria-hidden="true">${ghostFace}</span>${label?`<b>${label}</b>`:''}</span>`;
const icon = (file,label) => `<span class="ws-app"><img src="assets/${file}" alt="">${label}</span>`;
const msg = (speaker,text,kind='') => `<div class="ws-msg ${kind}"><small>${speaker}</small><p>${text}</p></div>`;
const frame = (file,title,meta,body,cls='') => `<div class="ws-window ${cls}"><header class="ws-bar">${icon(file,title)}${meta?`<span class="ws-bar-meta">${meta}</span>`:''}</header><div class="ws-body">${body}</div></div>`;
const winCtrl = '<span class="ap-ctrl" aria-hidden="true"><i>&#8211;</i><i>&#9634;</i><i>&#10005;</i></span>';
const appWin = (app,file,title,{ribbon='',right='',cls=''},body) => `<div class="ws-window ap ap-${app} ${cls}"><header class="ap-title"><img src="assets/${file}" alt=""><span class="ap-name">${title}</span>${right}${winCtrl}</header>${ribbon}<div class="ap-body">${body}</div></div>`;
const ribbon = (tabs,active,tools='') => `<div class="ap-ribbon" aria-hidden="true"><nav>${tabs.map(t=>`<span${t===active?' class="on"':''}>${t}</span>`).join('')}</nav>${tools?`<div class="ap-tools">${tools}</div>`:''}</div>`;
const sheet = (cols,rows,{sel='',mark=-1}={}) => {const letters='ABCDEFG'.slice(0,cols.length).split('');
 return `<table class="ap-grid"><thead><tr><th class="ap-corner"></th>${letters.map(l=>`<th${sel[0]===l?' class="on"':''}>${l}</th>`).join('')}</tr></thead><tbody><tr class="ap-hrow"><th>1</th>${cols.map(c=>`<td>${c}</td>`).join('')}</tr>${rows.map((r,i)=>{const n=i+2;return `<tr class="${i===mark?'ws-mark-row':''}"><th${sel.slice(1)===String(n)?' class="on"':''}>${n}</th>${r.map((c,j)=>`<td${sel===letters[j]+n?' class="ap-sel"':''}>${c}</td>`).join('')}</tr>`;}).join('')}<tr class="ap-blank"><th>${rows.length+2}</th>${cols.map(()=>'<td></td>').join('')}</tr></tbody></table>`;};
const fxBar = (ref,value) => `<div class="ap-fx" aria-hidden="true"><span class="ap-ref">${ref}</span><i>fx</i><span class="ap-fxv">${value}</span></div>`;
const sheetTabs = (tabs,status) => `<footer class="ap-sheets" aria-hidden="true">${tabs.map((t,i)=>`<span${i?'':' class="on"'}>${t}</span>`).join('')}<em>${status}</em></footer>`;
const table = (headers,rows,highlight=[],cls='') => `<table class="ws-table ${cls}"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map((r,i)=>`<tr class="${highlight.includes(i)?'ws-mark-row':''}">${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
const deadEnd = '<span class="ws-dead" aria-hidden="true">✕</span>';
const lock = '<svg class="ws-lock" viewBox="0 0 24 24" aria-hidden="true"><rect x="5" y="11" width="14" height="10" rx="2"/><path d="M8 11V8a4 4 0 0 1 8 0v3"/></svg>';
const bookmark = '<svg class="ws-bookmark" viewBox="0 0 24 24" aria-hidden="true"><path d="M6 3h12v18l-6-4-6 4z"/></svg>';
export function personToken(id,size='L') {
 const p=person(id);const v=verdicts[id];
 if(size==='S')return `<span class="ws-token-s v-${v}">${avatar(id)}<b>${p.name} · ${shortRoles[id]}</b></span>`;
 return `<div class="ws-token-l v-${v}">${avatar(id,'ws-avatar-l')}<div><p class="ws-name"><b>${p.name}</b><span>${p.department}</span></p><p class="ws-meta">${icon(toolIcons[p.ai],p.ai)}${id==='marcus'?'<span class="ws-plain-chip">Personal phone</span>':''}<span class="ws-verdict">${verdictLabels[v]}</span><span class="ws-badge">${badges[id]}</span></p></div></div>`;
}
